internal object DuaDoiDraft1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("जागने पर", "सारी स्तुति अल्लाह आस्तै ऐ, जिʼन्नै सानू मरने दे परैंत्त जीवन दित्ता, ते उसी बक्खी बापसी ऐ।", "नींद थमां जागने पर, अल्लाह दा शुक्रगुजार होना।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने जागने पर एह् पढ़ा-दिन दी शुरुआत शुक्रगुजार ते आख़िरत दे चेता कन्नै कीती।"),
        "dua_leaving_home" to DuaText("घर थमां निकलने पर", "अल्लाह दे नांऽ पर, में अल्लाह पर भरोसा करदा आं। अल्लाह दे अलावा कोई ताकत ते कोई ताकत नेईं ऐ।", "घर थमां बाह्र निकलदे समें, अल्लाह दी सुरक्षा आस्तै।", "स्वर्गदूत आखदे नः'तुंʼदा मार्गदर्शन कीता जंदा ऐ, तुंʼदी देखभाल कीती जंदी ऐ ते तुंʼदी सुरक्षा कीती जंदी ऐ', ते शैतान चली जंदा ऐ।"),
        "dua_anxiety_distress" to DuaText("चिंता ते दुख थमां राहत", "हे अल्लाह, में तुंʼदे च चिंता ते दुख शा, असहायता ते आलस्य शा, दुख ते कायरता शा, कर्जे दे बोझ शा ते लोकें दे वश च औने शा पनाह लैंदा आं।", "दुख, चिंता, कर्जे दा भार ते मानसिक तकलीफ दे समें।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने अक्सर एह् दुआ कीती-दुख, आलस्य ते कर्जे दी चिंता शा पनाह।"),
        "dua_sayyidul_istighfar" to DuaText("सैयद अल-इस्तिघफर (माफी दे प्रमुख)", "ऐ अल्लाह, तू मेरा रब ऐ, तेरे बगैर कुसै गी बी पूजा करने दा हक्क नेईं ऐ। तूने मिगी बनाया ऐ ते में तेरा दास आं, ते में तेरी वाचा ते वादे दा पालन करदा आं जेह्ड़ा में करी सकदा आं। में अपने कीते दे बुरे कम्में शा तेरी शरण लैंदा आं। में अपने पर तेरी कृपा गी मंजूर करदा आं ते में अपने पाप गी कबूल करदा आं, इस करियै मिगी माफ करी देओ, तेरे बगैर कोई पाप माफ नेईं करदा।", "सुबह ते सʼञ-पैगंबर सल्लल्लाह् अलैहि वसल्लम आसेआ सिखाई दी पश्चाताप दी सभनें शा शैल दुआ।", "जेह्ड़ा बी सʼञै गी निश्चत रूप कन्नै आखदा ऐ ते उस राती मरदा ऐ, ओह् परादीस च दाखल होग; एह् गै लागू होंदा ऐ जे भ्यागा आखेआ जंदा ऐ।"),
        "dua_parents" to DuaText("माता-पिता आस्तै विनती", "मेरे प्रभु, उंʼदे दौनें पर दया करो जिʼयां उʼनें मिगी लौह्का होने पर पालिआ हा।", "अपने माता-पिता आस्तै इक कुरानिक दुआ-बचपन च उंʼदी देखभाल दे बदले च।", "अपने माता-पिता आस्तै एह् दुआ बनाने दा हुकम खुद अल्लाह ने दित्ता ऐ।"),
        "dua_entering_mosque" to DuaText("मस्जिद च दाखल होना", "हे अल्लाह, मेरे लेई अपनी दया दे दरवाज़े खोल्हो।", "सज्जे पैर कन्नै मस्जिद च पैर रखदे समें।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने मस्जिद च दाखल होने आस्तै एह् दुआ सिखाई।"),
        "dua_morning_asbahna" to DuaText("प्रातःकाल दी याद", "असां भ्यागा दाखल होई गे आं ते सारी बादशाही अल्लाह दी सुबह च दाखल होई गेई ऐ। सारी स्तुति अल्लाह आस्तै ऐ। कुसै गी बी पूजा करने दा हक्क नेईं ऐ छड़ा अल्लाह दे, बगैर साझीदार दे। उसी दी बादशाही ऐ ते उसी दी स्तुति ऐ, ते ओह् हर चीज पर समर्थवान ऐ।", "भ्यागा सुन्नत दुआ दा पाठ कीता जंदा हा।", "दिन दी शुरुआत अल्लाह दी संप्रभुता ते उंʼदी एकता दी पुष्टि कन्नै होंदी ऐ।"),
        "dua_evening_amsayna" to DuaText("सʼञै दी याद", "असां सʼञै च दाखल होई गे आं ते सारी बादशाही सʼञै च दाखल होई गेई ऐ, ओह् अल्लाह दा ऐ। सारी स्तुति अल्लाह आस्तै ऐ। कुसै गी बी पूजा करने दा हक्क नेईं ऐ, छड़ा अल्लाह दे, बगैर साझीदार दे। बादशाही उसी दी ऐ ते स्तुति उसी दी ऐ, ते ओह् हर चीज पर समर्थवान ऐ।", "सʼञै इक सुन्नत दुआ दा पाठ कीता गेआ।", "राती दी शुरुआत अल्लाह दी संप्रभुता ते उंʼदी एकता दी पुष्टि कन्नै होंदी ऐ।"),
        "dua_bismillah_la_yadurru" to DuaText("सारे नुकसानें शा सुरक्षा", "अल्लाह दे नांऽ पर, जेह्दे नांऽ कन्नै धरती ते आसमानें च किश बी नुकसान नेईं पहुँचा सकदा, ते ओह् सारे सुनने आह्ला, जानने आह्ला ऐ।", "हर भ्यागा ते सʼञै त्रै बारी।", "जेह्ड़ा बी एह् भ्यागा ते सʼजैं त्रै बारी आखेआ, ओह्दे लेई किश बी नुकसान नेईं होग।"),
        "dua_raditu_billahi" to DuaText("भगवान दे रूप च अल्लाह दे कन्नै संतुष्टि", "में अपने प्रभु दे रूप च अल्लाह कन्नै, इस्लाम गी अपने धर्म दे रूप च ते मुहम्मद सल्लल्लाह् सल्लल्लाहु अलैहि वसल्लम गी अपने पैगंबर दे रूप च खुश आं।", "त्रै बारी भ्यागा ते सʼञै।", "क़ियामत दे दिन उʼनें गी खुश करना अल्लाह दा हक बनी जंदा ऐ।"),
        "dua_hasbiyallah" to DuaText("हसबीअल्लाह (अल्लाह काफी ऐ)", "मेरे लेई अल्लाह काफी ऐ, ओह्दे अलावा कोई पूज्य-प्रभु नेईं ऐ। में ओह्दे पर भरोसा करदा आं, ते ओह् शक्तिशाली संघासन दा रब ऐ।", "स'त्तें बारी भ्यागा ते सʼञै।", "कुरान दी इक आयत-इस दुनिया ते आख़िरत दी चिंताएं दे खलाफ अल्लाह काफी ऐ।"),
        "dua_subhanallah_wa_bihamdihi" to DuaText("सुभानअल्लाही वा बिहमदीही", "महिमावान ऐ अल्लाह ते सारी स्तुति उसी ऐ।", "दिन च सौ बारी।", "जेह्ड़ा कोई बी दिन च सौ बारी नेहा आखदा ऐ, ओह्दे पाप माफ करी दित्ता जंदा ऐ, भले गै ओह् समुंदर दे झाग जनेह् होन।"),
        "dua_tahleel_100" to DuaText("ला इलाहा इल्लल्लाहु वाहदहू", "कुसै गी बी पूजा करने दा हक्क नेईं ऐ छड़ा अल्लाह दे, बगैर साथी दे। उसी दी बादशाहत ऐ ते उसी दी स्तुति ऐ ते ओह् हर चीज पर काबले-जिकर ऐ।", "दिन च सौ बारी एह् आखना बड़ा चंगा ऐ।", "दसें दासें गी मुक्त करने दा इनाम, सौ भले कम्म लिखे गे, सौ पाप मिट गे ते सʼञै तक्कर शयतान शा सुरक्षा।"),
        "dua_leaving_mosque" to DuaText("मस्जिद छोड़ी दे", "हे अल्लाह, में तुंʼदे शा कृपा दी मंग करदा आं।", "खब्बे पैर कन्नै मस्जिद थमां बाह्र निकलदे समें।", "मस्जिद थमां बाह्र निकलदे समें अल्लाह थमां बरकत ते इंतजाम मंगना।"),
        "dua_after_adhan" to DuaText("अधान दे परैंत्त", "हे अल्लाह, इस परिपूर्ण पुकार ते स्थापत होने आह्ली प्रार्थना दे स्वामी, मुहम्मद सल्लल्लाह् वसीम अल-वसीला ते सद्गुण प्रदान करो, ते उʼनें गी उस सराह्ना आह्ले थाह्र तक्कर बधाओ जेह्दा तुस उंʼदे कन्नै वादा कीता ऐ।", "अधान पूरा होने दे परैंत्त।", "जेह्ड़ा बी एह् आखदा ऐ, उʼनें गी फैसले दे दिन पैगंबर सल्लल्लाहु अलैहि वसल्लम दी सिफ़ारिश मंजूर कीती जंदी।"),
        "dua_after_salah_istighfar" to DuaText("फरद सलाह दे परैंत्त", "में अल्लाह थमां माफी मंगदा आं (3 बारी)। ऐ अल्लाह, तुस सलाम दे रूप च ओ ते तुंʼदे शा शान्ति ऐ। हे महिमा ते सम्मान दे मालक, तुस बरकत आह्ले ओ।", "सलाम दे फौरन परैंत्त।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम हर इक फरजी नमाज़ दे परैंत्त एह् पाठ करदे हे।"),
        "dua_after_salah_help_dhikr" to DuaText("तुसें गी चेता करने च मेरी मदद करो", "हे अल्लाह, तुसें गी चेता करने, आभार व्यक्त करने ते सभनें शा अच्छे तरीके कन्नै तुंʼदी पूजा करने च मेरी मदद करो।", "हर इक नमाज़ दे परैंत्त-पैगंबर सल्लल्लाहु अलैहि वसल्लम ने मुआद (र) गी एह् कहने दी सलाह दित्ती।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम दी इक बशेश सलाह-पूजा च श्रेष्ठता ते स्थिरता।"),
        "dua_ayatul_kursi" to DuaText("सलाह दे परैंत्त आयत अल-कुर्सी", "अल्लाह-ओह्दे अलावा कोई पूज्य-प्रभु नेईं ऐ, जेह्ड़ा सर्वजीवन ऐ, जेह्ड़ा सभनें दा पालन-पोषण करदा ऐ। उसी च न सुस्ती ऐ ते न नींद। जेह्ड़ा किश आकाशें ते धरती च ऐ, उसी दा ऐ। उंʼदी इजाज़त दे बगैर ओह्दे कन्नै सिफ़ारिश करने आह्ला केह् ऐ? ओह् जानेआ जे उंʼदे पैह्लें केह् ऐ ते केह् उंʼदे परैंत्त केह् ऐ, ते उंʼदे ज्ञान च ओह् जेह्ड़ा किश बी ऐ, ओह्दे बगैर ओह् नेईं दसदे। उंʼदी कुर्शी आसमानें ते धरती पर फैली दी ऐ, ते उंʼदी रखवाली करने कन्नै ओह् थकदा नेईं ऐ। ओह् सर्वोच्च, महान ऐ।", "हर इक फरजी नमाज़ दे परैंत्त ते सोने शा पैह्लें।", "हर इक फरजी प्रार्थना दे परैंत्त इसगी पढ़ने आह्ले ते सोहे शा पैह्लें पढ़ने आह्ले दे बिच्च मौत दे अलावा होर किश नेईं ऐ; एह् भ्यागा तक्कर सुरक्षा प्रदान करदा ऐ।"),
        "dua_before_sleep" to DuaText("सौने शा पैह्लें", "हे अल्लाह, तेरे नांऽ पर मैं मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा/मरदा /", "बिस्तर पर लेटने परैंत्त।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने सोने शा पैह्लें एह् पढ़ा हा।"),
        "dua_sleep_tasbeeh" to DuaText("सोंदे शा पैह्लें तसबीह-ए-फ़ातिमी", "महिमावान ऐ अल्लाह (33), सारी स्तुति अल्लाह (33) आस्तै ऐ, अल्लाह सभनें शा महान ऐ (34)।", "सोंदे शा पैह्लें-पैगंबर सल्लल्लाहु अलैहि वसल्लम ने फातिमा ते अली (र) गी एह् सिखाया।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने आखेआ जे एह् तुंʼदे आस्तै इक नौकर दी तुलना च चंगा ऐ।"),
        "dua_sleep_qina_adhab" to DuaText("सʼजा थमां सुरक्षा", "ऐ अल्लाह, जिस दिन तुस अपने दासें गी जींद करदे ओ, उस दिन अपनी सज़ा शा मिगी बचाओ।", "त्रै बारी, सज्जे हाथ गी गाल दे खʼल्ल रक्खेआ।", "नींद गी मौत दी चेता च ते आख़िरत दी तैयारी च तब्दील करी दिंदा ऐ।"),
        "dua_bad_dream" to DuaText("इक बुरे सपने दे परैंत्त", "में शापित शयतान शा अल्लाह दी शरण मंगदा आं।", "इक बुरे सपने दे परैंत्तः त्रै बारी खब्बी बक्खी हलके-फुल्के थूकने, फ्ही दुए बक्खी मुड़ो।", "बुरे सपने कन्नै तुसें गी कोई नुकसान नेईं होग; एह्दे बारे च कुसै गी नेईं दस्सो।"),
        "dua_yunus" to DuaText("पैगंबर यूनुस (ए. ऐस्स.) दा दुआ", "तेरे बगैर कोई पूज्य-प्रभु नेईं ऐ। तेरी महिमा ऐ। मैं बदमाशां च शामल रेहा आं।", "व्हेल दे पेट च पैगंबर यूनुस (ए. ऐस्स.) दी दुआ-हर कठिनाई आस्तै।", "कोई बी मुसलमान जेह्ड़ा कुसै बी मामले च एह् दुआ करदा ऐ, अल्लाह उसी जवाब दिंदा ऐ।"),
        "dua_karb" to DuaText("दुख दे समें दुआ (कार्ब)", "कुसै गी बी पूजा करने दा हक्क नेईं ऐ छड़ा अल्लाह, जो पराक्रमी ते सहनशील ऐ। कुसै गी बी पूजा करने दा हक्क नेईं ऐ छड़ा अल्लाह, जेह्ड़ा पराक्रमी संघासन दा मालक ऐ। कुसै गी बी पूजा करने दा हक्क नेईं ऐ छड़ा अल्लाह, जेह्ड़ा आसमानें दा रब ऐ, धरती दा रब ऐ ते महान संघासन दा रब ऐ।", "गंभीर दुख ते कठिनाई दे समें च।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने दुख दे समें च एह् पढ़ा हा।"),
        "dua_ya_hayyu_ya_qayyum" to DuaText("या हयू या कयूम", "हे सदाबहार, हे सभनें दे पालनहार! तेरी दया कन्नै में मदद मंगदा आं।", "जिसलै कोई मामला बड़ा भारी होई जंदा ऐ।", "जिसलै बी पैगंबर जी गी किश परेशान करदा हा, ओह् एह् आखदे हे।"),
        "dua_hasbunallah" to DuaText("हसबुनाल्लाहु वा निमाल वकील", "अल्लाह साडे लेई काफी ऐ ते ओह् मामलें दा सभनें शा चंगा प्रबंधक ऐ।", "जिसलै कुसै दुश्मन शा डरो जां बड़े खतरे दा सामना करो।", "पैगंबर इब्राहिम (अ. स.) ने एह् अग्ग च सुट्टे जाने पर आखेआ ते पैगंबर सल्लल्लाहु अलैहि वसल्लम ने एह् खतरे दे समें आखेआ।"),
        "dua_entering_home" to DuaText("घर च दाखल होना", "अल्लाह दे नांऽ पर।", "घर च दाखल होने पर अल्लाह दा नांऽ दस्सो ते सलाम कन्नै नमाज़ आखो।", "जिसलै अंदर जाने ते खाने पर अल्लाह गी चेता कीता जंदा ऐ, तां शयतान आखदा ऐः इʼथे ठहरे जाने आस्तै कोई थाह्र नेईं ऐ ते तुंʼदे आस्तै रात दा खाना बी नेईं ऐ।"),
        "dua_travel" to DuaText("यात्रा आस्तै दुआ (सवारी)", "महिमावान ऐ ओह् जेह्ड़ा एह् असां गी सौंपी दित्ता ऐ, ते असीं एह् अपने लेई नेईं करी सकदे हे; ते निश्चत रूप कन्नै असीं अपने रब दी बक्खी बापस जाईङन।", "वाहन पर बैह्ने ते त्रै बारी अल्लाहू अकबर कहने दे परैंत्त।", "सुन्नत दी यात्रा दुआ-सुरक्षा ते आशीर्वाद आस्तै।"),
        "dua_entering_market" to DuaText("बजार च दाखल होना", "कुसै गी बी पूजा करने दा अधिकार नेईं ऐ, छड़ा अल्लाह दे, बगैर साथी दे। शासन उसी दा ऐ ते स्तुति ओह्दे गै ऐ। ओह् जीवन दिंदा ऐ ते मौत दा कारण होंदा ऐ, ते ओह् जींदा ऐ ते कदें नेईं मरदा। ओह्दे हाथ च सारा कुछ चंगा ऐ, ते ओह् हर चीज पर अधिकार रखदा ऐ।", "बजार च दाखल होने पर।", "हदीस च एह्दे आस्तै इक बड्डे इनाम (इक लक्ख भले कर्म) दा बर्णन ऐ।"),
        "dua_adam_forgiveness" to DuaText("पैगंबर आदम (अ. स.) दा दुआ", "ऐ हमारे रब, असां अपने पर जुल्म कीता ऐ, ते जे तुस सानू माफ नेईं करदे ते साडे पर रहम नेईं करदे, तां असीं निश्चत नुकसानें च शामल होई जाईङन।", "आदम ते हवा (ए. ऐस्स.) दे पश्चाताप दा दुआ।", "मानवता दा पैह्ला पश्चाताप-अल्लाह ने इसगी मंजूर करी लैता।"),
        "dua_abu_bakr" to DuaText("दुआ ने अबू बकर (र.) गी सिखाया", "ऐ अल्लाह, में अपने पर बड़ा जुल्म कीता ऐ ते तेरे बगैर कोई होर पाप माफ नेईं करदा, इस करियै मिगी अपनी बक्खी थमां क्षमा करो ते मुझ पर दया करो। निश्चय गै तुस क्षमाशील, दयावान ओ।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने अबू बकर अस-सिद्दीक (र. अ.) गी (ताशाहहूद दे परैंत्त) नमाज़ च आखना सिखाया।", "प्रार्थना दे अंत आस्तै सुन्नत दुआ।"),
        "dua_astaghfirullah_atubu" to DuaText("दैनिक इस्तिघफर", "में अल्लाह थमां माफ़ी मंगदा आं ते में पश्चाताप च उंʼदे बक्खी रुख करदा आं।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने दिन च सत्तें शा मते बारी माफ़ी मंगाई।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने आखेआः में अल्लाह थमां माफ़ी मंगदा आं ते दिन च सत्तें शा मते बारी उंʼदे शा पश्चाताप करदा आं।"),
        "dua_laylatul_qadr" to DuaText("लैलात अल-कदर आस्तै दुआ", "हे अल्लाह, तुस बड़े क्षमाशील ओ ते तुस क्षमा करना पसंद करदे ओ, इस करियै मिगी क्षमा करो।", "लैलत अल-कदर आस्तै आयशा (आर. ए.) गी सिखाया गेआ।", "रमज़ान ते लैलात अल-कदर दी आखरी राती आस्तै इक बशेश दुआ।"),
        "dua_family_coolness" to DuaText("अक्खें दी ठंडक (जीवनसाथी ते ञ्याणे)", "हे हमारे प्रभु, असां गी सा'नें दे जीवन-साथी ते संतानें थमां सा'नें दियें आँखि दी शीतलता प्रदान करो, ते असां गी धर्मियें दा नेता बनाओ।", "इक धर्मी जीवनसाथी ते ञ्याणें आस्तै इक कुरान दी दुआ।", "घर च शांति ते धर्मी ञ्याणें आस्तै।"),
        "dua_righteous_children" to DuaText("धर्मी संतानें आस्तै", "ऐ मेरे रब, मिगी अपनी तरफ थमां शुद्ध संतान प्रदान करो। तुस तोड़ी-तोड़ी दुआ करने आह्ले ओ।", "पैगंबर ज़कारिया (ए. ऐस्स.) दा दुआ।", "ञ्याणें दी तलाश करने आह्ले लोकें आस्तै इक कुरान दी दुआ।"),
        "dua_ibrahim_prayer_family" to DuaText("प्रार्थना दे संस्थापक", "ऐ मेरे रब, मिगी नमाज़ दा पालनकर्ता बनाओ ते मेरे बंश दे लोकें थमां। ऐ मेरे रब, मेरी नमाज़ मंजूर करो। ऐ मेरे रब, जिस दिन खाता स्थापत होग, उस दिन मिगी, मेरे माता-पिता गी ते विश्वासीएं गी माफ करी देओ।", "पैगंबर इब्राहिम (ए. ऐस्स.) दी दुआ अपने ते अपने वंशजें आस्तै।", "आमतौर पर प्रार्थना दे अंत च पाठ कीता जंदा ऐ।"),
        "dua_newlywed" to DuaText("नवविवाहितें गी बधाई।", "अल्लाह तुसें गी आशीर्वाद देवे, तुसें पर आशीर्वाद भेजे ते तुस दौनें गी अच्छाई कन्नै इकट्ठे करे।", "जिसलै कुसै गी उंʼदे ब्याह् पर बधाई दित्ती जंदी ऐ।", "सुन्नत ब्याह् आस्तै बधाई दिंदा ऐ।"),
        "dua_before_eating" to DuaText("खाने शा पैह्लें", "अल्लाह दे नांऽ पर। (जे भुला दित्ता गेआः) अल्लाह दे नांऽ पर, एह्दे शुरू च ते अंत च।", "खाने शा पैह्लें। जे तुस भुʼल गे ओ, तां किश हद्द तक्कर आख देओ।", "बिस्मिल्लाह आखने कन्नै शैतान भोजन बण्टने शा बची जंदा ऐ।"),
        "dua_after_eating" to DuaText("खाने दे परैंत्त", "सारी स्तुति अल्लाह आस्तै ऐ जिʼन्नै मिगी एह् खुआआआ ते मेरे आसेआ बगैर कुसै शक्ति जां शक्ति दे मेरे आस्तै एह् प्रदान कीता।", "खाना खत्म करने परैंत्त।", "जेह्ड़ा आखदा ऐ जे एह् माफ करी दित्ता गेआ ऐ, ओह्दे पिछले पाप।"),
        "dua_host" to DuaText("मेजबान आस्तै", "हे अल्लाह, तुस उʼनें गी जेह्ड़ा दित्ता ऐ, ओह्दे च उʼनें गी बरकत देओ, उʼनें गी माफ करो ते उंʼदे पर दया करो।", "मेजबान आस्तै, कुसै दे घर पर खाने दे परैंत्त।", "सुन्ना दे तरीके कन्नै मेजबान दा धन्नवाद करना।"),
    )
}
